const dirt = find_block({ names: ['dirt', 'grass_block', 'coarse_dirt'], max_distance: 16 });
if (!dirt) {
  return { done: false, detail: 'no ground within 16 blocks' };
}
await dig(dirt.x, dirt.y, dirt.z);
const left = await leave_at_depot('dirt', 1);
if (!left.ok) {
  return { done: false, detail: left.detail };
}
return { done: true, detail: 'broke up the ground and left it at the depot' };
